// ChirpStack v4 uplink -> Home Assistant (MQTT discovery + per-field state topics).
//
// Every field of the decoded payload ("object", from the device profile codec)
// becomes its own HA entity. Discovery configs are only re-sent when they change.
//
// Optional ChirpStack device tags (Device -> Tags) to tune the result:
//   ha_ignore        = true            skip this device completely
//   ha_skip          = a,b.c           skip these fields (flattened names)
//   ha_expire_after  = 7200            mark entities unavailable after N s without data
//   ha_unit_<field>  = °F              override the unit of a field
//   ha_class_<field> = temperature     override the HA device_class of a field

const DISCOVERY_PREFIX = 'homeassistant';
const STATE_PREFIX = 'chirpstack2ha';

// Field name pattern -> HA metadata (first match wins, only used for numbers).
// Covers common vendor spellings like "TempC_SHT", "Hum_SHT", "BatV".
// Anything unmatched becomes a plain sensor; fix outliers with device tags.
const RULES = [
    [/^rssi$/,                       { device_class: 'signal_strength', unit: 'dBm', diag: true }],
    [/^snr$/,                        { unit: 'dB', diag: true }],
    [/bat.*(v|volt)|vbat/,           { device_class: 'voltage', unit: 'V', diag: true }],
    [/bat/,                          { device_class: 'battery', unit: '%', diag: true }],
    [/temp/,                         { device_class: 'temperature', unit: '°C' }],
    [/hum/,                          { device_class: 'humidity', unit: '%' }],
    [/co2/,                          { device_class: 'carbon_dioxide', unit: 'ppm' }],
    [/tvoc/,                         { device_class: 'volatile_organic_compounds_parts', unit: 'ppb' }],
    [/press|baro/,                   { device_class: 'atmospheric_pressure', unit: 'hPa' }],
    [/lux|illum/,                    { device_class: 'illuminance', unit: 'lx' }],
    [/pm2_?5/,                       { device_class: 'pm25', unit: 'µg/m³' }],
    [/pm10/,                         { device_class: 'pm10', unit: 'µg/m³' }],
    [/energy|kwh/,                   { device_class: 'energy', unit: 'kWh', state_class: 'total_increasing' }],
    [/power|watt/,                   { device_class: 'power', unit: 'W' }],
    [/current|amp/,                  { device_class: 'current', unit: 'A' }],
    [/volt/,                         { device_class: 'voltage', unit: 'V' }],
];

const up = msg.payload;
if (!up || !up.deviceInfo || !up.deviceInfo.devEui) {
    return null;
}

const info = up.deviceInfo;
const tags = info.tags || {};
if (String(tags.ha_ignore).toLowerCase() === 'true') {
    return null;
}

const devEui = info.devEui.toLowerCase();
const skip = new Set(String(tags.ha_skip || '').split(',').map(s => s.trim()).filter(Boolean));
const expireAfter = parseInt(tags.ha_expire_after, 10);

// Decoded fields, nested objects flattened to "a_b". Arrays are skipped.
const fields = {};
function flatten(obj, prefix) {
    for (const [k, v] of Object.entries(obj)) {
        const key = (prefix ? prefix + '_' : '') + String(k).toLowerCase().replace(/[^a-z0-9_]/g, '_');
        if (v !== null && typeof v === 'object' && !Array.isArray(v)) {
            flatten(v, key);
        } else if (v !== null && !Array.isArray(v)) {
            fields[key] = v;
        }
    }
}
if (up.object && typeof up.object === 'object') {
    flatten(up.object, '');
} else if (typeof up.data === 'string' && up.data.length > 0) {
    // No codec in the device profile: accept payloads that are plain JSON text,
    // e.g. {"temperature": 22.18}. Anything else only yields RSSI/SNR.
    try {
        const decoded = JSON.parse(Buffer.from(up.data, 'base64').toString('utf8'));
        if (decoded && typeof decoded === 'object' && !Array.isArray(decoded)) {
            flatten(decoded, '');
        }
    } catch (e) {
        // Binary payload - needs a codec in ChirpStack.
    }
}

// Radio quality of the best receiving gateway.
if (Array.isArray(up.rxInfo) && up.rxInfo.length > 0) {
    const best = up.rxInfo.reduce((a, b) => ((b.rssi ?? -999) > (a.rssi ?? -999) ? b : a));
    if (typeof best.rssi === 'number') fields.rssi = best.rssi;
    if (typeof best.snr === 'number') fields.snr = best.snr;
}

// Entity name from the field name: "battery_voltage" -> "Battery voltage",
// abbreviations fully uppercase ("rssi" -> "RSSI", "ext_co2" -> "Ext CO2").
const ACRONYMS = new Set(['rssi', 'snr', 'co2', 'tvoc', 'voc', 'pm1', 'pm25', 'pm10', 'uv', 'gps', 'id', 'eui']);
function displayName(key) {
    return key.split('_').map((word, i) => {
        if (ACRONYMS.has(word)) return word.toUpperCase();
        return i === 0 ? word.charAt(0).toUpperCase() + word.slice(1) : word;
    }).join(' ');
}

const device = {
    identifiers: ['chirpstack_' + devEui],
    name: info.deviceName || devEui,
    model: info.deviceProfileName,
    manufacturer: 'LoRaWAN (' + (info.applicationName || 'ChirpStack') + ')',
    serial_number: devEui,
};

const published = context.get('discovery') || {};
const out = [];

for (const [key, value] of Object.entries(fields)) {
    if (skip.has(key)) {
        continue;
    }

    const isBool = typeof value === 'boolean';
    const isNumber = typeof value === 'number';
    const rule = isNumber ? RULES.find(([re]) => re.test(key)) : undefined;
    const meta = rule ? rule[1] : {};
    const component = isBool ? 'binary_sensor' : 'sensor';
    const uid = 'chirpstack_' + devEui + '_' + key;
    const stateTopic = STATE_PREFIX + '/' + devEui + '/' + key;

    const config = {
        name: displayName(key),
        unique_id: uid,
        object_id: uid,
        state_topic: stateTopic,
        device: device,
    };

    // HA rejects non-numeric states for most device classes, so overrides only apply to numbers too.
    const deviceClass = isNumber ? (tags['ha_class_' + key] || meta.device_class) : undefined;
    const unit = isNumber ? (tags['ha_unit_' + key] || meta.unit) : undefined;
    if (deviceClass) config.device_class = deviceClass;
    if (meta.diag) config.entity_category = 'diagnostic';
    if (Number.isFinite(expireAfter) && expireAfter > 0) config.expire_after = expireAfter;

    if (isBool) {
        config.payload_on = 'ON';
        config.payload_off = 'OFF';
    } else if (isNumber) {
        if (unit) config.unit_of_measurement = unit;
        config.state_class = meta.state_class || 'measurement';
    }

    // Discovery: only when new or changed (retained, so HA finds it after a restart).
    const configJson = JSON.stringify(config);
    if (published[uid] !== configJson) {
        out.push({
            topic: DISCOVERY_PREFIX + '/' + component + '/' + uid + '/config',
            payload: configJson,
            retain: true,
        });
        published[uid] = configJson;
    }

    // State: retained, so sensors that send rarely still show a value after an HA restart.
    out.push({
        topic: stateTopic,
        payload: isBool ? (value ? 'ON' : 'OFF') : String(value),
        retain: true,
    });
}

context.set('discovery', published);
node.status({ fill: 'green', shape: 'dot', text: (info.deviceName || devEui) + ': ' + Object.keys(fields).length + ' Felder' });

return [out];
